// Package cfr parses coreboot CFR option records (commonlib/include/commonlib/cfr.h).
//
// CFR is generated by ramstage at runtime and handed over in the coreboot
// table (LB_TAG_CFR). cbprov reads it from a CBFS file (FileName) or from a
// coreboot table dump captured on a running board.
package cfr

import (
	"errors"
	"fmt"
	"strings"
)

// FileName is the CBFS file cbprov reads the schema from: the raw LB_TAG_CFR record.
const FileName = "cfr.bin"

// Version is the only CFR_VERSION Parse accepts.
const Version = 0

// Kind is the option type.
type Kind int

const (
	KindForm Kind = iota
	KindEnum
	KindNumber
	KindBool
	KindVarchar
	KindComment
)

var kindNames = [...]string{"form", "enum", "number", "bool", "varchar", "comment"}

func (k Kind) String() string {
	if k < 0 || int(k) >= len(kindNames) {
		return fmt.Sprintf("kind(%d)", int(k))
	}
	return kindNames[k]
}

// MarshalText encodes the kind by name.
func (k Kind) MarshalText() ([]byte, error) {
	if k < 0 || int(k) >= len(kindNames) {
		return nil, fmt.Errorf("cfr: invalid kind %d", int(k))
	}
	return []byte(kindNames[k]), nil
}

// UnmarshalText decodes a kind name.
func (k *Kind) UnmarshalText(b []byte) error {
	for i, n := range kindNames {
		if n == string(b) {
			*k = Kind(i)
			return nil
		}
	}
	return fmt.Errorf("cfr: unknown kind %q", b)
}

// Flags mirror enum cfr_option_flags.
const (
	FlagReadOnly   = 1 << 0
	FlagInactive   = 1 << 1
	FlagSuppress   = 1 << 2
	FlagVolatile   = 1 << 3
	FlagRuntime    = 1 << 4
	FlagLockAtBoot = 1 << 5
)

// DisplayHex mirrors CFR_NUM_OPT_DISPFLAG_HEX in Option.DisplayFlags.
const DisplayHex = 1 << 0

var (
	ErrNoTable    = errors.New("cfr: no coreboot table found")
	ErrNoCFR      = errors.New("cfr: coreboot table has no CFR record")
	ErrReadOnly   = errors.New("read-only")
	ErrVolatile   = errors.New("volatile")
	ErrSuppressed = errors.New("suppressed")
)

// ForwardError reports an LB_TAG_FORWARD entry: the real table lives at Addr,
// outside the dump. Match it with errors.As and a ForwardError target.
type ForwardError struct{ Addr uint64 }

func (e ForwardError) Error() string {
	return fmt.Sprintf("cfr: coreboot table forwards to 0x%x", e.Addr)
}

// EnumValue is one choice of an enum option.
type EnumValue struct {
	Value  uint32 `json:"value"`
	UIName string `json:"ui_name"`
}

// Option is one CFR record. Forms carry their children in Options.
type Option struct {
	Kind         Kind        `json:"kind"`
	ObjectID     uint64      `json:"object_id"`
	DependencyID uint64      `json:"dependency_id,omitempty"`
	Flags        uint32      `json:"flags"`
	Name         string      `json:"name,omitempty"` // opt_name: the variable name; empty for forms and comments
	UIName       string      `json:"ui_name"`
	HelpText     string      `json:"help,omitempty"`
	Default      uint32      `json:"default"` // numeric kinds
	DefaultStr   string      `json:"default_str,omitempty"`
	Min          uint32      `json:"min,omitempty"`
	Max          uint32      `json:"max,omitempty"`
	Step         uint32      `json:"step,omitempty"`
	DisplayFlags uint32      `json:"display_flags,omitempty"`
	DepValues    []uint32    `json:"dep_values,omitempty"`
	EnumValues   []EnumValue `json:"enum_values,omitempty"`
	Options      []*Option   `json:"options,omitempty"` // children of a form
}

// Schema is the root of a parsed CFR tree.
type Schema struct {
	Version uint32    `json:"version"`
	Forms   []*Option `json:"forms"`
}

// Options returns all options that carry a variable name, depth first.
func (s *Schema) Options() []*Option {
	var out []*Option
	var walk func([]*Option)
	walk = func(opts []*Option) {
		for _, o := range opts {
			if o.Name != "" {
				out = append(out, o)
			}
			walk(o.Options)
		}
	}
	walk(s.Forms)
	return out
}

// Lookup finds an option by its variable name.
func (s *Schema) Lookup(name string) (*Option, bool) {
	for _, o := range s.Options() {
		if o.Name == name {
			return o, true
		}
	}
	return nil, false
}

// EnumName returns the UI name of enum value v.
func (o *Option) EnumName(v uint32) (string, bool) {
	for _, e := range o.EnumValues {
		if e.Value == v {
			return e.UIName, true
		}
	}
	return "", false
}

// EnumValue returns the value of the choice whose UI name matches name, ignoring case.
func (o *Option) EnumValue(name string) (uint32, bool) {
	for _, e := range o.EnumValues {
		if strings.EqualFold(e.UIName, name) {
			return e.Value, true
		}
	}
	return 0, false
}

// Validate checks whether v may be stored for o. Flag errors wrap
// ErrVolatile, ErrSuppressed or ErrReadOnly.
func (o *Option) Validate(v uint32) error {
	// VOLATILE and INACTIVE imply READONLY (cfr.c), so report the specific cause first.
	switch {
	case o.Flags&FlagVolatile != 0:
		return fmt.Errorf("%s: %w", o.Name, ErrVolatile)
	case o.Flags&FlagSuppress != 0:
		return fmt.Errorf("%s: %w", o.Name, ErrSuppressed)
	case o.Flags&FlagReadOnly != 0:
		return fmt.Errorf("%s: %w", o.Name, ErrReadOnly)
	}
	switch o.Kind {
	case KindBool:
		if v > 1 {
			return fmt.Errorf("%s: bool value %d is not 0 or 1", o.Name, v)
		}
	case KindEnum:
		if _, ok := o.EnumName(v); !ok {
			return fmt.Errorf("%s: %d is not a listed enum value", o.Name, v)
		}
	case KindNumber:
		if v < o.Min || v > o.Max {
			return fmt.Errorf("%s: %d out of range [%d, %d]", o.Name, v, o.Min, o.Max)
		}
		if o.Step > 1 && (v-o.Min)%o.Step != 0 {
			return fmt.Errorf("%s: %d is not min %d plus a multiple of step %d", o.Name, v, o.Min, o.Step)
		}
	default:
		return fmt.Errorf("%s: %s option has no numeric value", o.Name, o.Kind)
	}
	return nil
}
